<?php get_header(); ?>
<section class="archive-heading"><p class="eyebrow"><?php echo esc_html( msc_screen_identity()['name'] ); ?></p><h1>Reviews</h1></section>
<div class="review-archive-grid"><?php while ( have_posts() ) { the_post(); if ( get_post_field( 'post_password', get_the_ID() ) ) { continue; } $item = \MSC\Reviews::item( get_the_ID() ); if ( ! $item ) { continue; } $score = \MSC\Reviews::score( get_post_meta( get_the_ID(), '_msc_review_score', true ) ); ?><article class="review-archive-card"><a href="<?php the_permalink(); ?>"><div class="review-archive-image"><?php if ( has_post_thumbnail() ) { the_post_thumbnail( 'medium_large' ); } else { echo \MSC\Presentation::image( $item, '', 'medium_large' ); echo \MSC\Attribution::collect_image( $item ); } if ( null !== $score ) { echo \MSC\ReviewScores::badge_row( array( 'provider' => 'editorial', 'name' => msc_screen_identity()['name'], 'score' => $score, 'max' => 10, 'award' => \MSC\Reviews::award( $score ) ) ); } ?></div><p class="eyebrow"><?php echo esc_html( $item['data']['title'] ); ?></p><h2><?php the_title(); ?></h2></a><p class="review-byline"><?php echo esc_html( get_the_date() ); ?> · <?php the_author(); ?></p></article><?php } ?></div>
<div class="pagination"><?php the_posts_pagination(); ?></div>
<?php get_footer(); ?>
